import React, { useState, useEffect, useCallback } from 'react';
import './InteractiveCarousel.css';
import { useTranslation } from '../contexts/TranslationContext';

interface CarouselItem {
  id: number;
  title: string;
  video: string;
  description: string;
  image: string;
}

interface InteractiveCarouselProps {
  onGameClick: () => void;
}

const InteractiveCarousel: React.FC<InteractiveCarouselProps> = ({ onGameClick }) => {
  const { t } = useTranslation();
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isAutoPlaying, setIsAutoPlaying] = useState(true);
  const [isVideoPlaying, setIsVideoPlaying] = useState(false);
  const [hoverTimer, setHoverTimer] = useState<NodeJS.Timeout | null>(null);
  const [videoTimer, setVideoTimer] = useState<NodeJS.Timeout | null>(null);
  const videoRef = React.useRef<HTMLVideoElement>(null);

  const carouselItems: CarouselItem[] = [
    {
      id: 1,
      title: "FPS",
      video: "https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/BigBuckBunny.mp4",
      description: "Experience intense first-person action",
      image: "https://images.unsplash.com/photo-1556438064-2d7646166914?w=800&h=400&fit=crop"
    },
    {
      id: 2,
      title: "Racing",
      video: "https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ElephantsDream.mp4",
      description: "High-speed racing adventures",
      image: "https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=800&h=400&fit=crop"
    },
    {
      id: 3,
      title: "Adventure",
      video: "https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ForBiggerBlazes.mp4",
      description: "Epic quests and exploration",
      image: "https://images.unsplash.com/photo-1511512578047-dfb367046420?w=800&h=400&fit=crop"
    }
  ];

  const startVideoPlay = useCallback(() => {
    if (videoRef.current) {
      console.log('Starting video play for:', carouselItems[currentIndex].title);
      setIsVideoPlaying(true);

      // Reset video to beginning
      videoRef.current.currentTime = 0;

      // Try to play the video
      const playPromise = videoRef.current.play();

      if (playPromise !== undefined) {
        playPromise
          .then(() => {
            console.log('Video started playing successfully');

            // Stop video after 10 seconds
            const timer = setTimeout(() => {
              if (videoRef.current) {
                console.log('Stopping video after 10 seconds');
                videoRef.current.pause();
                setIsVideoPlaying(false);
              }
            }, 10000);

            setVideoTimer(timer);
          })
          .catch(err => {
            console.error('Video play failed:', err);
            setIsVideoPlaying(false);
          });
      }
    }
  }, [currentIndex, carouselItems]);

  const stopVideoPlay = useCallback(() => {
    if (videoTimer) {
      clearTimeout(videoTimer);
      setVideoTimer(null);
    }

    if (videoRef.current) {
      videoRef.current.pause();
      videoRef.current.currentTime = 0;
      setIsVideoPlaying(false);
    }
  }, [videoTimer]);

  const nextSlide = useCallback(() => {
    stopVideoAutoPlay();
    setCurrentIndex((prevIndex) => 
      prevIndex === carouselItems.length - 1 ? 0 : prevIndex + 1
    );
  }, [carouselItems.length, stopVideoAutoPlay]);

  const prevSlide = useCallback(() => {
    stopVideoAutoPlay();
    setCurrentIndex((prevIndex) => 
      prevIndex === 0 ? carouselItems.length - 1 : prevIndex - 1
    );
  }, [carouselItems.length, stopVideoAutoPlay]);

  const goToSlide = useCallback((index: number) => {
    stopVideoAutoPlay();
    setCurrentIndex(index);
  }, [stopVideoAutoPlay]);

  useEffect(() => {
    if (!isAutoPlaying) return;

    const interval = setInterval(nextSlide, 5000);
    return () => clearInterval(interval);
  }, [nextSlide, isAutoPlaying]);

  // Reset video loaded state when slide changes
  useEffect(() => {
    setVideoLoaded(false);
    setIsVideoPlaying(false);
  }, [currentIndex]);

  // Start video auto-play when video is loaded
  useEffect(() => {
    if (videoLoaded) {
      // Start video auto-play after a short delay to ensure smooth transition
      const timer = setTimeout(() => {
        startVideoAutoPlay();
      }, 500);

      return () => {
        clearTimeout(timer);
        stopVideoAutoPlay();
      };
    }
  }, [videoLoaded, startVideoAutoPlay, stopVideoAutoPlay]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      stopVideoAutoPlay();
    };
  }, [stopVideoAutoPlay]);

  const handleMouseEnter = () => {
    setIsAutoPlaying(false);

    // If video is already playing from auto-play, don't restart it
    if (!isVideoPlaying) {
      // Start timer to play video after 1 second of hover
      const timer = setTimeout(() => {
        startVideoAutoPlay();
      }, 1000);

      setHoverTimer(timer);
    }
  };

  const handleMouseLeave = () => {
    setIsAutoPlaying(true);

    // Clear hover timer if user leaves before video starts
    if (hoverTimer) {
      clearTimeout(hoverTimer);
      setHoverTimer(null);
    }

    // Don't stop the video if it's already playing from auto-play
    // Let it finish its 10-second cycle
  };

  const currentItem = carouselItems[currentIndex];

  return (
    <div 
      className="interactive-carousel"
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
    >
      <div className="carousel-container">
        <div className="slide-content">
          <div className="slide-text-overlay">
            <div className="slide-info">
              <h1 className="slide-title">{currentItem.title}</h1>
              <p className="slide-description">{currentItem.description}</p>
              <div className="slide-actions">
                <button 
                  className="slide-button primary"
                  onClick={onGameClick}
                >
                  <span className="btn-icon">▶</span>
                  {t('homepage.action.play')}
                </button>
                <button className="slide-button secondary">
                  <span className="btn-icon">ℹ</span>
                  {t('homepage.action.moreInfo')}
                </button>
              </div>
            </div>
          </div>

          <div className="slide-media">
            <img 
              src={currentItem.image}
              alt={currentItem.title}
              className={`slide-image-element ${isVideoPlaying ? 'hidden' : ''}`}
            />
            <video
              key={`video-${currentIndex}`}
              ref={videoRef}
              src={currentItem.video}
              className={`slide-video-element ${isVideoPlaying ? 'visible' : ''}`}
              muted
              playsInline
              loop={false}
              preload="metadata"
              onLoadStart={() => console.log('Video loading started for:', currentItem.title)}
              onCanPlay={() => console.log('Video can play for:', currentItem.title)}
              onError={(e) => {
                console.error('Video error for:', currentItem.title, e);
                setIsVideoPlaying(false);
              }}
              onLoadedData={() => {
                console.log('Video data loaded for:', currentItem.title);
                setVideoLoaded(true);
              }}
              onPlay={() => console.log('Video started playing for:', currentItem.title)}
              onPause={() => console.log('Video paused for:', currentItem.title)}
            />
            <div className={`media-overlay ${isVideoPlaying ? 'video-playing' : ''}`}></div>
            {isVideoPlaying && (
              <div className="video-indicator">
                <div className="pulse-ring"></div>
                <span className="live-badge">▶ PREVIEW</span>
              </div>
            )}

            {!videoLoaded && (
              <div className="video-loading-indicator">
                <div className="loading-spinner"></div>
                <span className="loading-text">Loading...</span>
              </div>
            )}

            {/* Progress indicator for current slide */}
            <div className="slide-progress">
              <div className="progress-dots">
                {carouselItems.map((_, index) => (
                  <div 
                    key={index}
                    className={`progress-dot ${index === currentIndex ? 'active' : ''}`}
                  />
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Navigation Arrows */}
      <button className="carousel-arrow left" onClick={prevSlide}>
        ‹
      </button>
      <button className="carousel-arrow right" onClick={nextSlide}>
        ›
      </button>

      {/* Dots Indicator */}
      <div className="carousel-dots">
        {carouselItems.map((_, index) => (
          <button
            key={index}
            className={`carousel-dot ${index === currentIndex ? 'active' : ''}`}
            onClick={() => goToSlide(index)}
          />
        ))}
      </div>
    </div>
  );
};

export default InteractiveCarousel;
